import{z as n,x as p,o as s,c as D,q as l,j as o,D as E,d as r,s as i,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"ARIES 直觉","description":"","frontmatter":{"title":"ARIES 直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/aries-recovery.md","filePath":"cs/aries-recovery.md","lastUpdated":1791413859000}'),d={name:"cs/aries-recovery.md"};function B(R,a,S,N,C,O){const t=p("Mermaid");return s(),D("div",null,[a[2]||(a[2]=l('<h1 id="aries-直觉" tabindex="-1">ARIES 直觉 <a class="header-anchor" href="#aries-直觉" aria-label="Permalink to &quot;ARIES 直觉&quot;">​</a></h1><div class="epigraph"><p>分析出谁脏、谁未提交；重做直到崩溃前的终点；再补偿回滚未完成事务——补偿本身也进日志。</p><footer>—— Mohan, Haderle, Lindsay, Pirahesh and Schwarz, ARIES, ACM TODS 1992</footer></div><p><a href="/cs/steal-noforce">上一课</a>钉死日志先行与 pageLSN。本课不重讲 fsync 顺序。缺口是：重启时日志很长、页可能落后或已经超前、回滚可能再次崩溃。ARIES 给出可重复的三阶段：分析、REDO、UNDO，并用补偿日志记录（CLR）保证 UNDO 幂等可中断。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只有 WAL 还没有算法。简单「从检查点重放全部」分不清哪些页已经新、哪些事务要撤。缺口不是新的日志格式口号，而是三张表：事务表、脏页表（分析阶段重建），然后<strong>从最小恢复 LSN 重做所有</strong>（重复历史），最后从后往前 UNDO 未提交，每撤一步写 CLR，CLR 指向下一步要撤的日志。</p><p><span class="marginnote">直觉类比：恢复像散场后清点剧场——分析是查票根弄清谁进场、谁没结账；REDO 把布景一帧帧倒回停电那一刻；UNDO 再把没结账观众拿走的道具一一收回，且收回动作同样登记在册（CLR），中途断手也能接着收。</span></p><p><span class="marginnote">重复历史：REDO 不跳过未提交事务的日志，页状态先回到崩溃瞬间，再 UNDO。这与「只 REDO 已提交」的策略不同，换来的是协议简单、支持 steal。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分析：从检查点扫到日志末，得到 loser 事务与脏页的最早 LSN。REDO：从该 LSN 重放，若页上 pageLSN 已更新则跳过。UNDO 按 loser 的 LastLSN 链回退；CLR 的 UndoNxtLSN 让第二次崩溃不必重做已补偿的步骤。本课不把锁表恢复、索引 SMO 日志的全部案例写完，只锁定这三阶段与 CLR。</p><p><span class="marginnote">术语翻译：loser（输家）是崩溃时还没提交的事务——它们的改动可能已随 steal 跑到盘上，恢复时必须撤销；赢家（已提交）的日志则全部重放，保证「说过的提交都算数」。</span></p>',10)),(s(),o(A,null,{default:E(()=>[i(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CKPT%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%20--%3E%20AN%5B%22%E5%88%86%E6%9E%90%3A%20%E4%BA%8B%E5%8A%A1%E8%A1%A8%2B%E8%84%8F%E9%A1%B5%E8%A1%A8%22%5D%0A%20%20AN%20--%3E%20REDO%5B%22REDO%20%E9%87%8D%E5%A4%8D%E5%8E%86%E5%8F%B2%22%5D%0A%20%20REDO%20--%3E%20UNDO%5B%22UNDO%20losers%20%2B%20CLR%22%5D%0A%20%20UNDO%20--%3E%20ACID%5B%22%E5%90%8E%E8%AF%BE%3A%20ACID%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[r("生理日志：以页为 REDO 单位，UNDO 可以是逻辑操作（如删除一条索引项）。这样 B+ 分裂不必在 REDO 时重演复杂路径，只要页内容回到日志所写。检查点把脏页表抄进日志，缩短分析。本课与"),e("a",{href:"/cs/buffer-dirty"},"缓冲"),r("对齐：换出脏页合法（steal），因为 UNDO 靠日志里的旧值或逻辑逆操作。")],-1)),a[5]||(a[5]=e("p",null,"生理日志让索引 SMO 不必在 REDO 时重演分裂路径，只要页映像回到日志所写。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"数字实例：日志 LSN 700 要改页 P，而盘上 P 的 pageLSN 已是 800，说明 700 的效果早已上盘，REDO 直接跳过；若 pageLSN 是 600，则应用这条日志并把 pageLSN 推到 700——逐条一比，重放多少遍结果都相同，这就是幂等。")],-1)),(s(),o(A,null,{default:E(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E5%8F%96%E4%B8%80%E6%9D%A1%20redo%20%E6%97%A5%E5%BF%97%3A%20LSN%20x%20%E6%94%B9%E9%A1%B5%20P%22%5D%20--%3E%20DIRT%7B%22P%20%E5%9C%A8%E8%84%8F%E9%A1%B5%E8%A1%A8%E4%B8%94%20x%20%E2%89%A5%20%E5%85%B6%20recoveryLSN%3F%22%7D%0A%20%20DIRT%20--%3E%7C%E5%90%A6%7C%20SKIP0%5B%22%E6%95%B4%E6%9D%A1%E8%B7%B3%E8%BF%87%22%5D%0A%20%20DIRT%20--%3E%7C%E6%98%AF%7C%20CMP%7B%22%E7%9B%98%E4%B8%8A%20P%20%E7%9A%84%20pageLSN%20%E2%89%A5%20x%3F%22%7D%0A%20%20CMP%20--%3E%7C%E6%98%AF%7C%20SKIP%5B%22%E6%97%A9%E5%B7%B2%E5%BA%94%E7%94%A8%3A%20%E8%B7%B3%E8%BF%87%22%5D%0A%20%20CMP%20--%3E%7C%E5%90%A6%7C%20APPLY%5B%22%E5%BA%94%E7%94%A8%E6%97%A5%E5%BF%97%2C%20%E6%8A%8A%20pageLSN%20%E6%8E%A8%E8%BF%9B%E5%88%B0%20x%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>ARIES 不是唯一恢复方案。影子页、写时复制文件系统走另一条路。本课也不覆盖分布式恢复、两阶段提交的协调器日志——那是<a href="/cs/two-pc">两阶段提交</a>。介质故障要归档日志与备份，不是一次重启三阶段能单独解决的。</p><p>模糊检查点允许检查点期间继续更新，分析阶段必须读到检查点结束之后的日志，这是为了缩短停机，不是省略 REDO。后课默认：本地崩溃后库能回到「已提交都在、未提交都像没发生」。事务的四个字母如何分工，后课才命名。</p><p>CLR 把 UNDO 变成可重做的 REDO 信息，第二次崩溃不会撤过头。这是「可中断回滚」的全部要点。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>分析重建的脏页表决定 REDO 起点；检查点越勤，分析越短。</p></li><li><p>后课 ACID 把这套恢复说成用户能理解的原子与持久。</p></li><li><p>WAL 给顺序；ARIES 给出分析、重复历史 REDO、带 CLR 的 UNDO。</p></li><li><p>steal/no-force 因此可实现，而不把半成品提交出去。</p></li><li><p>事务性质的用户说法（ACID）是后课缺口。</p></li><li><p>出处：Mohan et al., <em>TODS</em> 17(1), 1992；Gray and Reuter。</p></li></ul>',6))])}const h=n(d,[["render",B]]);export{m as __pageData,h as default};
